pages=[('', 'home','Home','Independent quantitative research and technology. Reproducible experiments, financial data engineering, and documented methods.',home,''),('research','research','Research','Explore the Alpha Covariance quantitative research register, hypotheses and research standards.',research,''),('systems','systems','Systems','Explore research software and quantitative engineering projects under review at Alpha Covariance.',systems,''),('lab','lab','Covariance Lab','Interactive two-asset covariance and portfolio volatility model using visitor-defined assumptions.',lab,'lab'),('notes','notes','Notes','Methodology, quantitative research and technical publication register at Alpha Covariance.',notes,''),('about','about','About','Learn about Alpha Covariance, an independent quantitative research and technology initiative.',about,''),('contact','contact','Contact','Contact Alpha Covariance about research, engineering or methodology collaboration.',contact,'contact'),('privacy','privacy','Privacy','Privacy practices for the Alpha Covariance public research website.',privacy,''),('404','404','Page not found','This Alpha Covariance page could not be found.',error404,'')]
for folder,name,title,desc,body,js in pages:
 dest = SITE/(folder if folder not in ('404',) else '')
 dest.mkdir(parents=True,exist_ok=True)
 (dest/('404.html' if name=='404' else 'index.html')).write_text(layout(name,title,desc,body,js),encoding='utf-8')

(SITE/'robots.txt').write_text('User-agent: *\nAllow: /\n# Crawlers must be able to read noindex headers; access is unlisted, not authenticated.\n',encoding='utf-8')
